import { describe, it, expect, vi, beforeEach } from "vitest";
import { screen } from "@testing-library/react";
import { renderWithProviders } from "../tests/utils";
import type { Flow, Stack } from "../types";

vi.mock("../InspectorContext", () => ({
  useInspectorContext: () => ({ logError: vi.fn() }),
}));

const makeFlow = (id: string): Flow => ({
  id,
  name: id,
  nodes: [],
  edges: [],
});

const makeStack = (flowId: string): Stack => ({
  frameId: "frame-1",
  flowId,
  stepId: "step-1",
  ended: false,
});

const defaultProps = {
  conversationList: [] as never[],
  conversationForSelectedElement: undefined,
  flowsLoading: false,
  flowsError: null,
};

describe("FlowSection", () => {
  describe("SWI-1146: error boundary on flow canvas", () => {
    beforeEach(() => {
      vi.resetModules();
      vi.spyOn(console, "error").mockImplementation(vi.fn());
    });

    it("renders the canvas when Flow renders successfully", async () => {
      vi.doMock("./Flow", () => ({
        Flow: () => <div data-testid="flow-canvas" />,
      }));
      const { FlowSection } = await import("./FlowSection");

      renderWithProviders(
        <FlowSection
          stackToShow={makeStack("my_flow")}
          flows={[makeFlow("my_flow")]}
          {...defaultProps}
        />,
      );

      expect(screen.getByTestId("flow-canvas")).toBeDefined();
    });

    it("shows an error placeholder when Flow throws during render", async () => {
      vi.doMock("./Flow", () => ({
        Flow: () => {
          throw new Error("flow import failed");
        },
      }));
      const { FlowSection } = await import("./FlowSection");

      renderWithProviders(
        <FlowSection
          stackToShow={makeStack("my_flow")}
          flows={[makeFlow("my_flow")]}
          {...defaultProps}
        />,
      );

      expect(screen.getByText("Could not render flow")).toBeDefined();
    });
  });
});
